('Furniture', 'NIGHT STAND (FIXED IN HEADBOARD): Ref Code: F8-03 Material/Finish/Color: Solid Wood / Ven…', 'Nos', 1800.0, 2520.0, 40.0, 'BBC/022026/00059', '2026-02-27'::date, 1, 'clipped · 1 quote(s) · last BBC/022026/00059 2026-02-27')
) as v(category, description, unit, cost_rate, sell_rate, markup_pct, ref, used_on, n, notes) loop
  if exists (select 1 from rate_items x where lower(btrim(x.description)) = lower(btrim(r.description)) and lower(coalesce(x.unit,'')) = lower(r.unit)) then continue; end if;
  pfx := rate_code_prefix(r.category);
  select coalesce(max(substring(code from '\d+$')::int), 0) + 1 into seq from rate_items where code like pfx || '-%';
  select id into pid from projects where enquiry_no = r.ref limit 1;
  insert into rate_items (code, category, description, unit, cost_rate, sell_rate, markup_pct, source_project_id, last_used, use_count, notes)
  values (pfx || '-' || lpad(seq::text, 3, '0'), r.category, r.description, r.unit, r.cost_rate, r.sell_rate, r.markup_pct, pid, r.used_on, r.n, r.notes);
end loop; end $x$;

